  match r, ph with
  | 1, 0 => farm1_0_1RB1LC_0LA1RB_1LD0RB_1LA1LA
  | _, _ => farm1_0_1RB1LC_0LA1RB_1LD0RB_1LA1LA  (* unreachable: 0 < r < N0 + st *)
  end.

