  match r, ph with | 1, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB1LC_0LA1RB_1LD0RB_1LA1LA (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.

