    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB1LC_0LC1RB_1LA0RB_______ : Fam := mkFam 2 [[S1;S1];[S0;S1]] [] [[]] Binary 1 [mkFill 1 [] 0 [] 0] StB S0 true [].
Local Notation FAM := fam_1RB1LC_0LC1RB_1LA0RB_______.

(** ** The ladder, as DATA

    2 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1LC_0LC1RB_1LA0RB_______ : list (LRule * list rstep) :=
  [(mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StB (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StA (mkS [S0;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StA (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) 0 2, [RB (SWin 2)])].
Local Notation lad := lad_1RB1LC_0LC1RB_1LA0RB_______.

Definition rules_1RB1LC_0LC1RB_1LA0RB_______ : list LRule := map fst lad.
Local Notation rules := rules_1RB1LC_0LC1RB_1LA0RB_______.

Lemma ladder_ok_1RB1LC_0LC1RB_1LA0RB_______ : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1LC_0LC1RB_1LA0RB_______ : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1LC_0LC1RB_1LA0RB_______. Qed.

