Definition rules_1RB1LC_1LA0RD_0LB0LA_1LA1RD : list LRule := map fst lad.
Local Notation rules := rules_1RB1LC_1LA0RD_0LB0LA_1LA1RD.

Lemma ladder_ok_1RB1LC_1LA0RD_0LB0LA_1LA1RD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1LC_1LA0RD_0LB0LA_1LA1RD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1LC_1LA0RD_0LB0LA_1LA1RD. Qed.

