(** ** The ladder, as DATA

    1 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1LC_1LA0RD_1LB0RA_0LB1RD : list (LRule * list rstep) :=
  [(mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StD (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)])].
Local Notation lad := lad_1RB1LC_1LA0RD_1LB0RA_0LB1RD.

Definition rules_1RB1LC_1LA0RD_1LB0RA_0LB1RD : list LRule := map fst lad.
Local Notation rules := rules_1RB1LC_1LA0RD_1LB0RA_0LB1RD.

Lemma ladder_ok_1RB1LC_1LA0RD_1LB0RA_0LB1RD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1LC_1LA0RD_1LB0RA_0LB1RD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1LC_1LA0RD_1LB0RA_0LB1RD. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
(* D[0] L<1^3+y0 0^1 1^1> R<>  ==>  D[0] L<0^1 1^2+y0 0^1 1^1> R<>   [2 steps] *)
