  mkLRule (mkC StD (mkS [S1;S1;S1] [S1] 1 0 [S0;S1]) S0 (mkS [] [] 0 0 []))
          (mkC StD (mkS [S0;S1;S1] [S1] 1 0 [S0;S1]) S0 (mkS [] [] 0 0 [])) 0 2.
Definition ch_arm11_1RB1LC_1LA0RD_1LB0RA_0LB1RD : list rstep := [RB (SWin 2)].
Lemma ok_arm11_1RB1LC_1LA0RD_1LB0RA_0LB1RD :
  check_arm tm true true rules arm11_1RB1LC_1LA0RD_1LB0RA_0LB1RD ch_arm11_1RB1LC_1LA0RD_1LB0RA_0LB1RD = true.
Proof. vm_compute. reflexivity. Qed.
Lemma sound_arm11_1RB1LC_1LA0RD_1LB0RA_0LB1RD : RuleSound tm true true arm11_1RB1LC_1LA0RD_1LB0RA_0LB1RD.
Proof. eapply arm_sound; [exact rules_sound_1RB1LC_1LA0RD_1LB0RA_0LB1RD | exact ok_arm11_1RB1LC_1LA0RD_1LB0RA_0LB1RD]. Qed.

