Definition pins_1RB1LC_1LA0RD_1RA1LB_0LA1RD : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_1RB1LC_1LA0RD_1RA1LB_0LA1RD pins_1RB1LC_1LA0RD_1RA1LB_0LA1RD).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB1LC_1LA0RD_1RA1LB_0LA1RD : Fam := mkFam 2 [[S1;S1;S1];[S1;S1;S0]] [] [[S1]] Binary 1 [mkFill 1 [] 0 [1] 0] StD S0 true [].
Local Notation FAM := fam_1RB1LC_1LA0RD_1RA1LB_0LA1RD.

(** ** The ladder, as DATA

    3 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1LC_1LA0RD_1RA1LB_0LA1RD : list (LRule * list rstep) :=
  [(mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StD (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StC (mkS [S0;S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S1;S1;S1] [] 0 0 [])) 0 3, [RB (SWin 3)]);
   (mkLRule (mkC StC (mkS [S0;S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S1;S1;S1] [] 0 0 [])) 0 3, [RB (SWin 3)])].
Local Notation lad := lad_1RB1LC_1LA0RD_1RA1LB_0LA1RD.

Definition rules_1RB1LC_1LA0RD_1RA1LB_0LA1RD : list LRule := map fst lad.
Local Notation rules := rules_1RB1LC_1LA0RD_1RA1LB_0LA1RD.

Lemma ladder_ok_1RB1LC_1LA0RD_1RA1LB_0LA1RD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1LC_1LA0RD_1RA1LB_0LA1RD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1LC_1LA0RD_1RA1LB_0LA1RD. Qed.

