(** ** The ladder, as DATA

    3 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1LC_1LA0RD_1RA1LB_0LC1RD : list (LRule * list rstep) :=
  [(mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StD (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StB (mkS [S1;S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 [])) (mkC StB (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1] [] 0 0 [])) 0 3, [RB (SWin 3)]);
   (mkLRule (mkC StB (mkS [S1;S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 [])) (mkC StB (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1] [] 0 0 [])) 0 3, [RB (SWin 3)])].
Local Notation lad := lad_1RB1LC_1LA0RD_1RA1LB_0LC1RD.

Definition rules_1RB1LC_1LA0RD_1RA1LB_0LC1RD : list LRule := map fst lad.
Local Notation rules := rules_1RB1LC_1LA0RD_1RA1LB_0LC1RD.

Lemma ladder_ok_1RB1LC_1LA0RD_1RA1LB_0LC1RD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1LC_1LA0RD_1RA1LB_0LC1RD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1LC_1LA0RD_1RA1LB_0LC1RD. Qed.

(** ** The arms, as DATA

