(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_1RB1LC_1LA1LA_0RD0LB_1LB1RD : NeverQuasiHaltsTr tm_1RB1LC_1LA1LA_0RD0LB_1LB1RD.
Proof.
  apply (boardph_neverqhtr tm_1RB1LC_1LA1LA_0RD0LB_1LB1RD pins_1RB1LC_1LA1LA_0RD0LB_1LB1RD FAM 1
                           iarm_1RB1LC_1LA1LA_0RD0LB_1LB1RD 0 1
                           farm_1RB1LC_1LA1LA_0RD0LB_1LB1RD 1 1
                           fm1_1RB1LC_1LA1LA_0RD0LB_1LB1RD fm2_1RB1LC_1LA1LA_0RD0LB_1LB1RD 0 vis_1RB1LC_1LA1LA_0RD0LB_1LB1RD
                           [0] 0 21).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
