Lemma fm12_1RB1LC_1LC1LA_0RD0LB_1LB1RD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  fm1_1RB1LC_1LC1LA_0RD0LB_1LB1RD r ph + fm2_1RB1LC_1LC1LA_0RD0LB_1LB1RD r ph
  + (length (f_pre (fam_fill FAM ph)) + length (f_suf (fam_fill FAM ph)))
